-- Seed the Privacy Policy and Terms of Service pages, and stop the footer's
-- copyright year going stale.
--
-- This is the same content as the alembic migration
-- `f7c2a1d94e08_seed_legal_pages.py`, as a plain script for a production database
-- that is migrated by hand. Run EITHER this or the migration -- running both is
-- harmless, because every statement here is a no-op when the rows already exist.
--
-- What it does:
--   1. Adds one `cms_pages` row per legal page, so both appear in the admin.
--   2. Adds the document itself as that page's single `sections` row, which is
--      what makes it editable clause by clause in the Sections editor.
--   3. Rewrites a hard-coded year in the footer's copyright line to the `{year}`
--      token the site expands to the current year.
--
-- Safe to re-run: the inserts are ON CONFLICT DO NOTHING and the update only
-- touches a copyright line that still has a literal year in it, so wording an
-- admin has edited is never overwritten.
--
--   psql "$DATABASE_URL" -f alembic/seeds/seed_legal_pages.sql

BEGIN;

-- Privacy Policy
INSERT INTO cms_pages (name)
VALUES ('Privacy Policy')
ON CONFLICT (name) DO NOTHING;

INSERT INTO sections (page_id, section_id, template_id, content)
SELECT p.id, 'privacy_policy', 'default', CAST('{"title": "Privacy Policy", "last_updated": "25 August 2026", "intro": "Self Awareness Society runs meditation and self-awareness programmes in Singapore and Malaysia. This policy explains what personal information we collect when you use this website, why we collect it, who we share it with, and the choices you have. It covers this website and the enquiries, member accounts and programme registrations made through it.", "clauses": [{"heading": "Who we are", "body": "Self Awareness Society is the organisation responsible for the personal information described here.\n\nAddress: Self Awareness Centre HQ, 10 Anson Road, Singapore\nEmail: enquiry@selfawareness.com.sg\nPhone: +65 6222 5115"}, {"heading": "Information we collect", "body": "We collect only what a given action needs.\n\nEnquiries: your name, email address, phone number, and the subject and message you send us.\n\nAccounts: your name, preferred name, email address and phone number, and — if you choose to add them — your date of birth, gender, occupation, address and profile photo.\n\nProgramme registrations: the last four digits of your NRIC or passport number, your preferred language, meal preference, any health conditions you tell us about, the name and phone number of an emergency contact, how you heard about us, and the name and number of anyone who introduced you.\n\nPayments: the amount, status and reference of your payment. Card and bank details are entered on our payment provider''s page and are never seen or stored by us.\n\nTechnical information: your device''s IP address and basic request logs, kept so the service stays secure and available."}, {"heading": "Why we collect it", "body": "To answer your enquiries; to create and secure your account and send the one-time codes you sign in with; to register you for a programme and prepare for it, including catering and accessibility; to reach your emergency contact if something happens during a programme; to take and reconcile payment; to send you information about a programme you have registered for; and to keep the records we are required by law to keep.\n\nWe send newsletters and programme announcements only to people who asked for them, and every one of those messages can be stopped at any time."}, {"heading": "Health information", "body": "The health conditions you disclose during registration are used only to keep you safe during a programme, and are seen only by the staff running it. You do not have to give them, but withholding something relevant may mean we cannot accept your registration for certain programmes."}, {"heading": "Who we share it with", "body": "We do not sell your personal information.\n\nWe share it with our payment provider so a payment can be taken; with the service providers who host this website, store its files and deliver its email and messages, all of whom act on our instructions; with the facilitators of a programme you have registered for, limited to what running it requires; and with the authorities where the law requires it."}, {"heading": "Where your information is held", "body": "Our systems are hosted in Singapore. Where a service provider processes information outside Singapore or Malaysia, we require them to protect it to a standard comparable to the one described here."}, {"heading": "How long we keep it", "body": "Enquiries are kept for up to two years after we have answered them. Account and registration records are kept while your account is active and for up to seven years afterwards, because payment and attendance records must be retained for tax and accounting purposes. Anything we no longer need is deleted or anonymised."}, {"heading": "Keeping it secure", "body": "Data travels over encrypted connections, access to it is limited to the staff whose role requires it, and signing in uses a one-time code rather than a shared password. No system is perfectly secure, so please do not send us sensitive information by email or public message."}, {"heading": "Cookies and similar technologies", "body": "This site stores a small amount of data in your browser to keep you signed in and to remember your preferences. These are necessary for the site to work and are cleared when you sign out. We do not use advertising cookies."}, {"heading": "Your rights", "body": "You may ask us for a copy of the information we hold about you, ask us to correct it, ask us to delete your account, or withdraw a consent you have given. Write to enquiry@selfawareness.com.sg and we will respond within 30 days. If our response does not satisfy you, you may complain to the Personal Data Protection Commission in Singapore, or to the equivalent authority where you live."}, {"heading": "Children", "body": "This website is not intended for children under 13, and we do not knowingly collect their information. A young person attending a programme is registered by a parent or guardian, who provides the details and consents on their behalf. If you believe we hold a child''s information without that consent, contact us and we will remove it."}, {"heading": "Changes to this policy", "body": "We update this policy when our practices change. The date at the top shows when it was last revised, and material changes are announced on this page before they take effect."}, {"heading": "Contact us", "body": "Questions about this policy, or about the information we hold on you:\n\nEmail: enquiry@selfawareness.com.sg\nPhone: +65 6222 5115\nAddress: Self Awareness Centre HQ, 10 Anson Road, Singapore"}]}' AS JSON)
FROM cms_pages p
WHERE p.name = 'Privacy Policy'
ON CONFLICT (section_id) DO NOTHING;

-- Terms of Service
INSERT INTO cms_pages (name)
VALUES ('Terms of Service')
ON CONFLICT (name) DO NOTHING;

INSERT INTO sections (page_id, section_id, template_id, content)
SELECT p.id, 'terms_of_service', 'default', CAST('{"title": "Terms of Service", "last_updated": "25 August 2026", "intro": "These terms govern your use of this website and your registration for programmes run by Self Awareness Society. By creating an account, submitting an enquiry or registering for a programme, you agree to them. Please read them together with our Privacy Policy, which explains how we handle your personal information.", "clauses": [{"heading": "Who may use this site", "body": "You may use this site if you are 18 or older and able to enter into a binding agreement. A registration for someone under 18 must be made by their parent or guardian, who accepts these terms on their behalf."}, {"heading": "Your account", "body": "You sign in with a one-time code sent to your email address or phone number, so keeping those contact details accurate and under your control is what keeps your account secure. Tell us promptly if you think someone else has access to it. Anything done through your account is treated as done by you.\n\nThe details you give us — including your phone number and your emergency contact — must be true and current. We may suspend or close an account used to give false information or to disrupt a programme."}, {"heading": "Registering for a programme", "body": "A registration is a request for a place, not yet a confirmed one. Your place is confirmed once we accept it and the required payment has been received. Programmes have limited capacity and places are taken in the order they are paid for.\n\nSome programmes carry prerequisites, a minimum age, or health requirements. We may decline or cancel a registration that does not meet them."}, {"heading": "Fees and payment", "body": "Programme fees are shown on the programme''s page in the currency stated there. Where a programme allows it, you may pay a deposit to hold your place and settle the balance by the due date shown on your registration. A place whose balance is unpaid after that date may be released to someone else.\n\nPayments are taken by our payment provider. We do not receive or store your card details."}, {"heading": "Cancellations, transfers and refunds", "body": "If you cancel, tell us in writing as early as you can. A deposit reserves a place that we then hold for you and is generally not refundable; whether the balance is refundable depends on how close to the start date you cancel, and the terms published with each programme apply.\n\nIf we cancel or reschedule a programme, you may transfer to another date or have what you paid for it refunded in full. We are not responsible for travel or accommodation you booked separately."}, {"heading": "During a programme", "body": "Our programmes involve meditation, reflection and physical stillness for extended periods. They are not medical treatment and are not a substitute for it. Take medical advice before attending if you have a physical or mental health condition, and tell us about anything relevant when you register.\n\nYou remain responsible for your own wellbeing during a programme, and should stop and speak to a facilitator if you feel unwell."}, {"heading": "Conduct", "body": "Our centres are shared spaces. Please follow the facilitators'' instructions, respect the silence and privacy of other participants, and do not record or photograph anyone without their agreement. We may ask someone whose behaviour endangers or seriously disturbs others to leave, without a refund."}, {"heading": "Our content", "body": "The text, images, recordings and teaching materials on this site belong to Self Awareness Society or to those who licensed them to us. You may read, download and print them for your own personal, non-commercial use. Republishing them, selling them or teaching from them requires our written permission."}, {"heading": "Content you submit", "body": "You keep ownership of what you send us — enquiries, testimonials, photographs. By sending it you allow us to use it for the purpose you sent it for, and to publish a testimonial under the name you gave unless you tell us otherwise. Please do not send anything unlawful, or anything you do not have the right to share."}, {"heading": "Availability of the site", "body": "We aim to keep this site available and its information accurate, but we cannot guarantee it will be uninterrupted or free of errors. Programme dates, venues, fees and facilitators may change, and the details confirmed to you when you registered are the ones that apply."}, {"heading": "Limitation of liability", "body": "So far as the law allows, our liability arising from your use of this site or from a programme is limited to the amount you paid for the programme concerned. Nothing in these terms limits liability for death or personal injury caused by our negligence, for fraud, or for anything else that cannot lawfully be limited."}, {"heading": "Governing law", "body": "These terms are governed by the laws of Singapore, and the courts of Singapore have jurisdiction over any dispute arising from them."}, {"heading": "Changes to these terms", "body": "We may update these terms. The date at the top shows when they were last revised, and the version in force when you registered is the one that applies to that registration. Continuing to use the site after a change means you accept the updated terms."}, {"heading": "Contact us", "body": "Questions about these terms:\n\nEmail: enquiry@selfawareness.com.sg\nPhone: +65 6222 5115\nAddress: Self Awareness Centre HQ, 10 Anson Road, Singapore"}]}' AS JSON)
FROM cms_pages p
WHERE p.name = 'Terms of Service'
ON CONFLICT (section_id) DO NOTHING;

-- Footer copyright: "(c) 2024 ..." becomes "(c) {year} ...", which the site
-- renders as the current year from then on.
UPDATE sections
SET content = jsonb_set(
        content::jsonb,
        '{copyright_text}',
        to_jsonb(regexp_replace(content->>'copyright_text', '\d{4}', '{year}'))
    )::json
WHERE section_id = 'footer'
  AND content->>'copyright_text' ~ '\d{4}';

COMMIT;
